CREATE TABLE IF NOT EXISTS fee_accounts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),student_id UUID NOT NULL REFERENCES app_users(id),academic_year TEXT NOT NULL,semester TEXT NOT NULL,fee_type TEXT NOT NULL,amount NUMERIC(12,2) NOT NULL CHECK(amount>=0),paid_amount NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(paid_amount>=0),balance NUMERIC(12,2) GENERATED ALWAYS AS (amount-paid_amount) STORED,due_date DATE,status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','PARTIAL','PAID','OVERDUE','WAIVED')),receipt_number TEXT,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS fee_payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),fee_account_id UUID NOT NULL REFERENCES fee_accounts(id),student_id UUID NOT NULL REFERENCES app_users(id),amount NUMERIC(12,2) NOT NULL CHECK(amount>0),status TEXT NOT NULL CHECK(status IN ('INITIATED','SUCCESS','FAILED','REFUNDED')),gateway_reference TEXT,receipt_number TEXT,paid_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_fee_student ON fee_accounts(student_id);CREATE INDEX IF NOT EXISTS idx_payment_student ON fee_payments(student_id);
